-- =============================================================================
-- BASE DE DATOS GEOGRÁFICA Y TRANSACCIONAL DCI - POSTGIS 15
-- Proyecto: Caracterización Georreferenciada de la Población Infantil (0-4 años)
-- Metodología: Modelo de Producción Estadística (MPE) - INEC / CEISH-ESPOCH
-- =============================================================================

CREATE EXTENSION IF NOT EXISTS postgis;
CREATE EXTENSION IF NOT EXISTS postgis_topology;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- 1. TABLA DE BRIGADISTAS Y ENCUESTADORES ESPOCH (PAO NUTRICIÓN)
CREATE TABLE IF NOT EXISTS mpe_brigadistas (
    id_brigadista VARCHAR(50) PRIMARY KEY,
    nombres VARCHAR(200) NOT NULL,
    cedula_ofuscada VARCHAR(50) NOT NULL,
    carrera VARCHAR(150) NOT NULL,
    pao VARCHAR(100) NOT NULL,
    rol VARCHAR(150) NOT NULL,
    dupla VARCHAR(50) NOT NULL,
    posicion VARCHAR(50) NOT NULL,
    zona_codigo VARCHAR(50) NOT NULL,
    zona_nombre VARCHAR(200) NOT NULL,
    estado VARCHAR(100) DEFAULT 'ACTIVO - CERTIFICADO TEM',
    vigencia VARCHAR(100) DEFAULT '21 Sep 2026 - 13 Nov 2026',
    convenio VARCHAR(150) DEFAULT 'ESPOCH / Fundación Ayuda en Acción',
    telefono_soporte VARCHAR(50) DEFAULT '',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 2. TABLA DE PREDIOS Y VIVIENDAS DETECTADAS POR IA (SAMv13)
CREATE TABLE IF NOT EXISTS mpe_predios_sam (
    id_predio SERIAL PRIMARY KEY,
    codigo_predio VARCHAR(50) UNIQUE NOT NULL,
    anillo_censal INT NOT NULL,
    centralidad_pdot VARCHAR(150) NOT NULL,
    parroquia VARCHAR(50) DEFAULT 'San Andrés',
    canton VARCHAR(50) DEFAULT 'Guano',
    estado_visita VARCHAR(50) DEFAULT 'PENDIENTE',
    geom GEOMETRY(Point, 4326),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 3. TABLA DE CARACTERIZACIÓN INFANTIL (MPE - 147 VARIABLES)
CREATE TABLE IF NOT EXISTS mpe_ninos_dci (
    id_nino UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    codigo_kobo VARCHAR(100) UNIQUE,
    id_brigadista VARCHAR(50) REFERENCES mpe_brigadistas(id_brigadista),
    id_predio INT REFERENCES mpe_predios_sam(id_predio),
    edad_meses INT CHECK (edad_meses >= 0 AND edad_meses <= 59),
    sexo VARCHAR(20) CHECK (sexo IN ('MASCULINO', 'FEMENINO')),
    peso_kg NUMERIC(5,2),
    talla_cm NUMERIC(5,2),
    zscore_peso_edad NUMERIC(4,2),
    zscore_talla_edad NUMERIC(4,2),
    zscore_peso_talla NUMERIC(4,2),
    diagnostico_nutricional VARCHAR(100),
    consentimiento_bioetico_ceish BOOLEAN DEFAULT TRUE,
    fecha_levantamiento DATE,
    geom_hogar GEOMETRY(Point, 4326),
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 4. TABLA DE AUDITORÍA Y TRAZABILIDAD DE SINCRONIZACIÓN KOBO
CREATE TABLE IF NOT EXISTS mpe_auditoria_kobo (
    id_sync SERIAL PRIMARY KEY,
    fecha_sync TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    registros_sincronizados INT NOT NULL DEFAULT 0,
    usuario_operador VARCHAR(150) NOT NULL,
    hash_integridad_sha256 VARCHAR(64),
    estado_sync VARCHAR(50) NOT NULL
);

-- POBLACIÓN INICIAL: 73 BRIGADISTAS OFICIALES DE NUTRICIÓN ESPOCH (v2.5.0)
ON CONFLICT (id_brigadista) DO NOTHING;
